public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextInt();
        }

        int total = 0;
        for (int v : A) total += v;

        if (total < K) {
            System.out.println(0);
            return;
        }

        // Check if K is achievable at all
        if (!canSum(A, K)) {
            System.out.println(0);
            return;
        }

        // Try removing each card
        for (int i = 0; i < N; i++) {
            int[] rest = new int[N - 1];
            int idx = 0;
            for (int j = 0; j < N; j++) {
                if (j != i) rest[idx++] = A[j];
            }
            if (!canSum(rest, K)) {
                System.out.println(1);
                return;
            }
        }

        // If removing any single card still leaves K achievable,
        // then we need to remove at least 2. But given constraints,
        // it can be proven that answer is at most 2 in such cases.
        System.out.println(2);
    }

    static boolean canSum(int[] arr, int target) {
        boolean[] dp = new boolean[target + 1];
        dp[0] = true;
        for (int v : arr) {
            for (int s = target; s >= v; s--) {
                if (dp[s - v]) dp[s] = true;
            }
        }
        return dp[target];
    }
}

