public class Main {
    static int[] A;
    static int N, K;
    static int maxDisjoint;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt(); K = sc.nextInt();
        A = new int[N];
        for (int i = 0; i < N; i++) A[i] = sc.nextInt();

        maxDisjoint = 0;
        boolean[] used = new boolean[N];
        dfs(used, 0);
        System.out.println(maxDisjoint);
    }

    static void dfs(boolean[] used, int count) {
        maxDisjoint = Math.max(maxDisjoint, count);
        // Find a subset of unused cards summing to K
        List<Integer> avail = new ArrayList<>();
        for (int i = 0; i < N; i++) if (!used[i]) avail.add(i);
        int m = avail.size();
        for (int mask = 1; mask < (1 << m); mask++) {
            int sum = 0;
            for (int i = 0; i < m; i++) if ((mask >> i & 1) == 1) sum += A[avail.get(i)];
            if (sum == K) {
                for (int i = 0; i < m; i++) if ((mask >> i & 1) == 1) used[avail.get(i)] = true;
                dfs(used, count + 1);
                for (int i = 0; i < m; i++) if ((mask >> i & 1) == 1) used[avail.get(i)] = false;
            }
        }
    }
}

