public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int K = fs.nextInt();
        int[] A = new int[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextInt();

        // If K == 0, empty subset always achieves 0, impossible to prevent.
        // But typical constraints for this problem have K >= 1.
        if (K == 0) {
            System.out.println(-1);
            return;
        }

        Arrays.sort(A);

        // dp[s] = whether some subset of currently processed cards can make sum s
        // only for s in [0, K-1]. Sums >= K are irrelevant.
        boolean[] dp = new boolean[K];
        dp[0] = true;

        int notNecessary = 0;

        for (int i = 0; i < N; i++) {
            int a = A[i];

            // Check if this card is "necessary":
            // if there exists x in [K-a, K-1] reachable by other cards,
            // then adding this card can complete to K, so it is necessary.
            boolean necessary = false;
            int from = Math.max(0, K - a);
            for (int s = from; s < K; s++) {
                if (dp[s]) {
                    necessary = true;
                    break;
                }
            }

            if (!necessary) notNecessary++;

            // Update dp with this card
            if (a < K) {
                for (int s = K - 1 - a; s >= 0; s--) {
                    if (dp[s]) dp[s + a] = true;
                }
            }
            // if a >= K, it never helps form a sum < K, so no dp update needed
        }

        // Minimum eaten cards = number of cards that are necessary
        System.out.println(N - notNecessary);
    }
}

