#define MAX_N 200
#define MAX_K 10000

int main() {
    int N, K;
    scanf("%d %d", &N, &K);
    int A[MAX_N];
    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
    }

    // dp[s] = number of ways to reach sum s (boolean reachable)
    bool dp[MAX_K + 1];
    memset(dp, 0, sizeof(dp));
    dp[0] = true;

    int total = 0;
    for (int i = 0; i < N; i++) {
        total += A[i];
        for (int s = K; s >= A[i]; s--) {
            if (dp[s - A[i]])
                dp[s] = true;
        }
    }

    if (!dp[K]) {
        printf("0\n");
        return 0;
    }

    // Check for each card: if removing it makes K unreachable
    for (int i = 0; i < N; i++) {
        bool temp[MAX_K + 1];
        memset(temp, 0, sizeof(temp));
        temp[0] = true;
        for (int j = 0; j < N; j++) {
            if (j == i) continue;
            for (int s = K; s >= A[j]; s--) {
                if (temp[s - A[j]])
                    temp[s] = true;
            }
        }
        if (!temp[K]) {
            printf("1\n");
            return 0;
        }
    }

    // Otherwise, we need at least 2 cards removed.
    // Try all pairs
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            bool temp[MAX_K + 1];
            memset(temp, 0, sizeof(temp));
            temp[0] = true;
            for (int k = 0; k < N; k++) {
                if (k == i || k == j) continue;
                for (int s = K; s >= A[k]; s--) {
                    if (temp[s - A[k]])
                        temp[s] = true;
                }
            }
            if (!temp[K]) {
                printf("2\n");
                return 0;
            }
        }
    }

    // In worst case, we need to remove many cards.
    // Greedy removal: repeatedly remove the card that appears in most subsets summing to K
    int removed = 0;
    bool used[MAX_N];
    memset(used, 0, sizeof(used));

    while (1) {
        memset(dp, 0, sizeof(dp));
        dp[0] = true;
        for (int i = 0; i < N; i++) {
            if (used[i]) continue;
            for (int s = K; s >= A[i]; s--) {
                if (dp[s - A[i]])
                    dp[s] = true;
            }
        }
        if (!dp[K]) break;

        // Count how many ways each unused card contributes
        int contrib[MAX_N];
        memset(contrib, 0, sizeof(contrib));

        for (int i = 0; i < N; i++) {
            if (used[i]) continue;
            bool temp[MAX_K + 1];
            memset(temp, 0, sizeof(temp));
            temp[0] = true;
            for (int j = 0; j < N; j++) {
                if (j == i || used[j]) continue;
                for (int s = K; s >= A[j]; s--) {
                    if (temp[s - A[j]])
                        temp[s] = true;
                }
            }
            // Count subsets that use this card
            int count = 0;
            for (int s = K - A[i]; s >= 0; s--) {
                if (temp[s] && s + A[i] == K) count++;
            }
            contrib[i] = count;
        }

        // Remove the card with maximum contribution
        int max_idx = -1, max_val = -1;
        for (int i = 0; i < N; i++) {
            if (!used[i] && contrib[i] > max_val) {
                max_val = contrib[i];
                max_idx = i;
            }
        }
        used[max_idx] = true;
        removed++;
    }

    printf("%d\n", removed);
    return 0;
}

