#define INF 1000000000

int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;

    int *A = (int*)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) scanf("%d", &A[i]);

    /* dp[s] = minimum number of eaten cards needed so that
       after processing some prefix, sum s is still achievable
       by remaining cards.
       Initialize with "eat none": only sum 0 achievable with cost 0.
    */
    int *dp = (int*)malloc(sizeof(int) * (K + 1));
    int *ndp = (int*)malloc(sizeof(int) * (K + 1));

    for (int s = 0; s <= K; s++) dp[s] = INF;
    dp[0] = 0;

    for (int i = 0; i < N; i++) {
        for (int s = 0; s <= K; s++) ndp[s] = INF;

        for (int s = 0; s <= K; s++) {
            if (dp[s] == INF) continue;

            /* Option 1: eat this card */
            if (dp[s] + 1 < ndp[s]) ndp[s] = dp[s] + 1;

            /* Option 2: keep this card, but maybe don't use it in subset */
            if (dp[s] < ndp[s]) ndp[s] = dp[s];

            /* Option 3: keep and use it */
            if (s + A[i] <= K && dp[s] < ndp[s + A[i]]) {
                ndp[s + A[i]] = dp[s];
            }
        }

        int *tmp = dp;
        dp = ndp;
        ndp = tmp;
    }

    /* We want minimum eaten cards such that K is NOT achievable.
       That means among all final states where K is unreachable,
       i.e. dp[K] should not exist. This DP directly tracks minimum
       eaten cards while preserving reachability of each sum.
       So answer is the minimum number of eaten cards over all choices
       that do not allow K.

       Equivalent:
       Let total eaten = e.
       If after all decisions K is reachable, dp[K] <= e.
       To force K unreachable, we need a different DP.

       Instead, compute maximum number of cards we can keep while
       ensuring K remains unreachable via boolean subset states.
       Simpler approach below is needed.
    */

    free(dp);
    free(ndp);

    /* Correct DP:
       dp[s] = maximum number of kept cards such that among kept cards,
       achievable sums include s, and K is still not achievable.
       We maintain only sums < K; transitions that create K are forbidden.
       At end, answer = N - max kept.
    */
    int *best = (int*)malloc(sizeof(int) * K);
    int *next = (int*)malloc(sizeof(int) * K);

    for (int s = 0; s < K; s++) best[s] = -INF;
    best[0] = 0;

    for (int i = 0; i < N; i++) {
        for (int s = 0; s < K; s++) next[s] = best[s];

        for (int s = 0; s < K; s++) {
            if (best[s] < 0) continue;

            /* Keep card but do not use it in the subset currently representing s */
            if (best[s] + 1 > next[s]) next[s] = best[s] + 1;

            /* Keep card and use it, only if sum stays below K */
            if (s + A[i] < K && best[s] + 1 > next[s + A[i]]) {
                next[s + A[i]] = best[s] + 1;
            }
            /* If s + A[i] == K, forbidden: that would make K achievable */
        }

        int *tmp = best;
        best = next;
        next = tmp;
    }

    int maxKeep = 0;
    for (int s = 0; s < K; s++) {
        if (best[s] > maxKeep) maxKeep = best[s];
    }

    printf("%d\n", N - maxKeep);

    free(best);
    free(next);
    free(A);
    return 0;
}

