#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;
    vector<int> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];

    sort(A.begin(), A.end());

    // dp[s] = whether sum s is achievable using processed cards
    vector<char> dp(K + 1, 0);
    dp[0] = 1;

    int answer = 0;

    for (int i = 0; i < N; i++) {
        int x = A[i];

        // If there exists a reachable sum in [K-x, K-1],
        // then this card can participate in some subset summing to K.
        bool necessary = false;
        int L = max(0, K - x);
        for (int s = L; s < K; s++) {
            if (dp[s]) {
                necessary = true;
                break;
            }
        }

        if (necessary) answer++;

        // Update subset-sum DP
        for (int s = K - x; s >= 0; s--) {
            if (dp[s]) dp[s + x] = 1;
        }
    }

    // Minimum cards to eat = number of cards that are "necessary"
    // for forming K in some way.
    cout << answer << '\n';
    return 0;
}
